style.css:
@-moz-document domain("twitch.tv") {
/* 01. Viewport-aligned canvas for the page and the player gutters. */
html { color-scheme: dark !important; }
html,
.video-player,
[data-a-target="video-player"] {
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* 02. Twitch component tokens. Theme roots may be nested in portals or popouts. */
html, body,
.tw-root--theme-light, .tw-root--theme-dark,
.tw-root--theme-light .theme--dark, .tw-root--theme-dark .theme--light,
.theme--light, .theme--dark {
  --font-base: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  --font-display: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  --color-background-body: transparent !important;
  --color-background-base: rgba(1,22,10,.75) !important;
  --color-background-accent: rgba(12,91,39,.56) !important;
  --color-background-alt: rgba(2,26,12,.82) !important;
  --color-background-alt-2: rgba(6,46,22,.84) !important;
  --color-background-float: rgba(2,23,11,.97) !important;
  --color-background-tooltip: rgba(1,20,10,.97) !important;
  --color-background-modal: rgba(2,23,11,.97) !important;
  --color-background-input: rgba(4,43,20,.95) !important;
  --color-background-input-focus: rgba(4,43,20,.95) !important;
  --color-background-input-checkbox-checked: #00e85c !important;
  --color-background-input-checkbox-checked-active: #38ff87 !important;
  --color-background-input-checked: #00c84c !important;
  --color-background-interactable-hover: rgba(12,91,39,.56) !important;
  --color-background-interactable-active: rgba(10,115,43,.61) !important;
  --color-background-interactable-selected: rgba(4,54,27,.58) !important;
  --color-background-button: #00e85c !important;
  --color-background-button-brand: #00e85c !important;
  --color-background-button-brand-hover: #38ff87 !important;
  --color-background-button-focus: #38ff87 !important;
  --color-background-button-hover: #38ff87 !important;
  --color-background-button-primary-default: #00e85c !important;
  --color-background-button-primary-hover: #38ff87 !important;
  --color-background-button-primary-active: #00c84c !important;
  --color-background-button-secondary-default: rgba(4,57,26,.88) !important;
  --color-background-button-secondary-hover: rgba(12,91,39,.56) !important;
  --color-background-button-secondary-active: rgba(10,115,43,.61) !important;
  --color-background-button-text-default: transparent !important;
  --color-background-button-text-hover: rgba(12,91,39,.56) !important;
  --color-background-button-text-active: rgba(10,115,43,.61) !important;
  --color-background-button-icon-hover: rgba(12,91,39,.56) !important;
  --color-background-button-icon-active: rgba(10,115,43,.61) !important;
  --color-background-button-icon-primary-hover: rgba(12,91,39,.56) !important;
  --color-background-button-icon-primary-active: rgba(10,115,43,.61) !important;
  --color-background-tag-default: rgba(4,54,27,.58) !important;
  --color-background-tag-hover: rgba(12,91,39,.56) !important;
  --color-background-tag-active: rgba(10,115,43,.61) !important;
  --color-background-range: rgba(28,240,102,.36) !important;
  --color-background-range-fill: #00e85c !important;
  --color-background-toggle: rgba(4,43,20,.95) !important;
  --color-background-toggle-checked: #00e85c !important;
  --color-text-base: #d9ffe6 !important;
  --color-text-alt: #9ee5b6 !important;
  --color-text-alt-2: #70b68b !important;
  --color-text-link: #68ffa3 !important;
  --color-text-link-hover: #b5ffd1 !important;
  --color-text-link-active: #7fffac !important;
  --color-text-link-focus: #00ff66 !important;
  --color-text-link-visited: #68ffa3 !important;
  --color-text-input: #effff3 !important;
  --color-text-input-placeholder: #a6efbb !important;
  --color-text-button: #d9ffe6 !important;
  --color-text-button-brand: #001b09 !important;
  --color-text-button-focus: #001b09 !important;
  --color-text-button-hover: #001b09 !important;
  --color-text-button-active: #001b09 !important;
  --color-text-button-primary: #001b09 !important;
  --color-text-button-secondary: #d9ffe6 !important;
  --color-text-button-secondary-hover: #d9ffe6 !important;
  --color-text-button-secondary-active: #d9ffe6 !important;
  --color-text-button-text: #b7ffd0 !important;
  --color-text-button-icon: #7fffac !important;
  --color-text-toggle-checked-icon: #001b09 !important;
  --color-text-tag: #9ee5b6 !important;
  --color-text-tag-hover: #d9ffe6 !important;
  --color-text-tooltip: #d9ffe6 !important;
  --color-text-brand: #7fffac !important;
  --color-fill-brand: #00ff66 !important;
  --color-fill-button-icon: #7fffac !important;
  --color-fill-button-icon-focus: #7fffac !important;
  --color-fill-button-icon-active: #7fffac !important;
  --color-border-base: rgba(32,243,107,.18) !important;
  --color-border-region: rgba(32,243,107,.18) !important;
  --color-border-tab: rgba(32,243,107,.18) !important;
  --color-border-tab-focus: #00ff66 !important;
  --color-border-brand-decorative: #00ff66 !important;
  --color-border-button-focus: #00ff66 !important;
  --color-border-input: rgba(28,240,102,.36) !important;
  --color-border-input-hover: rgba(45,255,118,.50) !important;
  --color-border-input-focus: #00ff66 !important;
  --color-border-input-checkbox-checked: #00ff66 !important;
  --color-border-input-checkbox-focus: #00ff66 !important;
  --color-border-range-handle: #00ff66 !important;
  --color-border-toggle-focus: #00ff66 !important;
  --color-border-interactable-selected: #00ff66 !important;
  --color-border-balloon: rgba(28,240,102,.36) !important;
  --color-accent: #00ff66 !important;
}

html, body, button, input, select, textarea,
[role="textbox"], [contenteditable="true"],
.tw-font-display, .tw-font-base {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}

body, #root, #root > .tw-root, .twilight-root {
  color: #d9ffe6 !important;
}
body, #root, #root > .tw-root, .twilight-root,
.twilight-main, .root-scrollable, .scrollable-area,
main, [role="main"], [data-a-target="main-content"],
[data-a-target="browse-page"], .directory-root,
.channel-root, .channel-root__main, .channel-root__main--with-chat,
.channel-root__info, .channel-root__player-container + div,
.channel-root__right-column, .channel-info-content,
.whispers, .clips-root {
  background-color: transparent !important;
}
a { text-decoration-color: rgba(69,255,137,.65) !important; }
a:hover { text-decoration-color: #b5ffd1 !important; }
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* 03. Global navigation, channel toolbar and followed-channel rail. */
nav.top-nav, .top-nav__menu, [data-a-target="top-nav-container"],
.channel-header, .channel-info-bar, .channel-root__nav,
[data-a-target="channel-header"], [data-a-target="channel-tab-bar"] {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(24,241,106,.22) !important;
  box-shadow: inset 0 -1px 0 rgba(24,241,106,.22) !important;
  -webkit-backdrop-filter: blur(11px) saturate(125%) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
nav.top-nav .top-nav__menu, nav.top-nav [data-a-target="top-nav-container"] {
  background-color: transparent !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
/* Left rail: brighter green at the right edge beside the video. */
.side-nav,
.side-nav__theme-wrapper {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to left,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  box-shadow: inset -2px 0 0 rgba(67,255,134,.90),
    inset -10px 0 18px -11px rgba(0,255,102,.75),
    5px 0 22px -8px rgba(0,255,102,.60) !important;
}
.side-nav .side-nav__theme-wrapper,
.side-nav .side-nav__overlay-wrapper,
.side-nav__theme-wrapper .side-nav__overlay-wrapper {
  background: transparent !important;
  box-shadow: none !important;
}
.side-nav .side-nav__scrollable_content,
.side-nav__theme-wrapper .side-nav__scrollable-content,
.side-nav__theme-wrapper .side-nav-section,
.side-nav__theme-wrapper .tw-c-background-base,
.side-nav__theme-wrapper .tw-c-background-alt,
.side-nav__theme-wrapper .tw-c-background-alt-2 {
  background-color: transparent !important;
}
.side-nav h2, .side-nav h3, .stream-chat-header h2 {
  color: #9ee5b6 !important;
}
.side-nav-card, .side-nav a[data-a-target="side-nav-card"],
.dashboard-side-nav__link {
  color: #c0ffd5 !important;
  border-radius: 7px !important;
}
.side-nav-card:hover, .side-nav a[data-a-target="side-nav-card"]:hover,
.side-nav-card[aria-current="page"], .dashboard-side-nav__link:hover,
.dashboard-side-nav__link--active,
.top-nav a[data-a-target="top-nav-link"]:hover,
.top-nav a.navigation-link:hover,
.channel-root__nav a[aria-current="page"] {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
.top-nav a.navigation-link[aria-current="page"] {
  color: #7fffac !important;
  box-shadow: inset 0 -2px 0 #00ff66 !important;
}
.top-nav a[href="/"] svg, .top-nav a[href="https://www.twitch.tv/"] svg,
[data-a-target="home-link"] svg, [data-test-selector="tw-logo"] svg,
[data-test-selector="tw-logo"] {
  color: #00ff66 !important;
  fill: currentColor !important;
  filter: drop-shadow(0 0 4px rgba(0,255,102,.85)) drop-shadow(0 0 12px rgba(0,255,102,.35)) !important;
}
.top-nav a[href="/"] svg path:not([fill="none"]),
[data-a-target="home-link"] svg path:not([fill="none"]) {
  fill: currentColor !important;
}

/* Twitch scales this decorative backdrop past the player and behind the info. */
.channel-root__player > div > div[style*="scale("][style*="background-color"] {
  background-color: transparent !important;
}

/* Stream metadata sits flush below the player on live channels and VODs. */
.channel-info-content > section:first-child {
  background-color: transparent !important;
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 48%, rgba(1,19,11,.16) 100%) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.90),
    inset 0 10px 18px -11px rgba(0,255,102,.75),
    0 -5px 22px -8px rgba(0,255,102,.60) !important;
}

/* Anchor the fade to the bottom of Stream Information, behind the next section. */
.channel-info-content {
  isolation: isolate !important;
}
.channel-info-content > section:first-child {
  position: relative !important;
}
.channel-info-content > section:first-child::after {
  content: "" !important;
  position: absolute !important;
  top: 100% !important;
  right: 0 !important;
  left: 0 !important;
  height: 200px !important;
  z-index: -1 !important;
  pointer-events: none !important;
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.24) 45%, rgba(1,19,11,0) 100%) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.90),
    inset 0 10px 18px -11px rgba(0,255,102,.75) !important;
}

/* The About card and the channel and Plus goal card surfaces. */
.about-section__panel--content,
.about-section__actions [role="region"] > div {
  background: transparent !important;
}

/* One glowing divider across the channel panel grid, above its first row. */
.channel-panels {
  padding-top: 16px !important;
}
.channel-panels .channel-panels-container::before {
  content: "" !important;
  position: absolute !important;
  right: 0 !important;
  bottom: 100% !important;
  left: 0 !important;
  height: 2px !important;
  margin-bottom: 10px !important;
  background-color: rgba(67,255,134,.90) !important;
  box-shadow: 0 0 8px rgba(0,255,102,.75),
    0 0 18px rgba(0,255,102,.35) !important;
  pointer-events: none !important;
}

/* 04. Directory, shelves, search results and stream cards. */
[data-a-target="preview-card-image-link"],
[data-test-selector="preview-card-image-link"],
[data-a-target="card-image-link"], .tw-card__image,
.game-card__image, .preview-card-thumbnail {
  border-radius: 7px !important;
  outline: 1px solid rgba(28,240,102,.36) !important;
  outline-offset: 0 !important;
}
[data-a-target="preview-card-image-link"]:hover,
[data-test-selector="preview-card-image-link"]:hover,
[data-a-target="card-image-link"]:hover, .tw-card__image:hover,
.game-card__image:hover, .preview-card-thumbnail:hover {
  outline-color: rgba(105,255,154,.73) !important;
  box-shadow: 0 0 18px rgba(0,255,102,.14) !important;
}
[data-a-target="preview-card-title-link"], [data-a-target="preview-card-title"],
[data-test-selector="TitleAndChannel"], [data-a-target="card-title"],
[data-a-target="stream-title"], [data-test-selector="stream-info-card-component__subtitle"] {
  color: #d9ffe6 !important;
}
[data-a-target="preview-card-title-link"]:hover,
[data-a-target="card-title"]:hover,
[data-a-target="preview-card-channel-link"]:hover,
[data-a-target="preview-card-game-link"]:hover {
  color: #b5ffd1 !important;
}
[data-a-target="preview-card-channel-link"],
[data-a-target="preview-card-game-link"], [data-a-target="browse-sort-dropdown"],
[data-test-selector="stream-info-card-component__description"] {
  color: #9ee5b6 !important;
}
[data-a-target="search-result-card"], .search-result-card,
[data-a-target="video-info"], [data-a-target="channel-about-panel"],
[data-test-selector="channel-panel"], .channel-panels-panel,
.channel-panel-container, .dashboard-panel,
[data-a-target="channel-schedule-segment"], .schedule-segment {
  background-color: rgba(1,22,10,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
  border-radius: 10px !important;
}
[data-a-target="search-result-card"]:hover, .search-result-card:hover,
[data-a-target="channel-schedule-segment"]:hover, .schedule-segment:hover {
  box-shadow: inset 0 0 0 1px rgba(105,255,154,.73), 0 0 18px rgba(0,255,102,.14) !important;
}
[data-a-target="tag"], [data-a-target="tw-tag"],
[data-test-selector="tag"], .tw-tag {
  background-color: rgba(4,54,27,.58) !important;
  color: #9ee5b6 !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
[data-a-target="tag"]:hover, [data-a-target="tw-tag"]:hover,
[data-test-selector="tag"]:hover, .tw-tag:hover {
  background-color: rgba(12,91,39,.56) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.50) !important;
}
[data-a-target="tw-tabs"] a[aria-current="page"],
[role="tab"][aria-selected="true"] {
  color: #7fffac !important;
  border-color: #00ff66 !important;
  box-shadow: inset 0 -2px 0 #00ff66 !important;
}
.tw-border-t, .tw-border-b, .tw-border-l, .tw-border-r, hr {
  border-color: rgba(32,243,107,.18) !important;
}

/* 05. Chat, highlights, settings and composer. */
.stream-chat, .stream-chat-container, .video-chat, .chat-room,
[data-a-target="chat-shell"] {
  background-color: rgba(1,22,10,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
}
.stream-chat .stream-chat-container,
.stream-chat .chat-room, .stream-chat .chat-list,
.stream-chat-container .chat-room, .video-chat .chat-list,
.chat-room__content, .chat-list, .chat-scrollable-area__message-container,
.stream-chat .chat-input-tray__open, .stream-chat .chat-input-container__open {
  background-color: transparent !important;
}
/* Right rail: mirror the left rail and use one glass layer. */
.channel-root__right-column > div,
[data-a-target="right-column-chat-bar"] .chat-shell {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to right,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  border-left-color: rgba(67,255,134,.90) !important;
  box-shadow: inset 2px 0 0 rgba(67,255,134,.90),
    inset 10px 0 18px -11px rgba(0,255,102,.75),
    -5px 0 22px -8px rgba(0,255,102,.60) !important;
}
.channel-root__right-column .chat-shell,
.channel-root__right-column .stream-chat,
.channel-root__right-column .stream-chat-container,
.channel-root__right-column .video-chat,
.channel-root__right-column .chat-room,
[data-a-target="right-column-chat-bar"] .chat-shell .stream-chat,
[data-a-target="right-column-chat-bar"] .chat-shell .stream-chat-container,
[data-a-target="right-column-chat-bar"] .chat-shell .chat-room {
  background: transparent !important;
  box-shadow: none !important;
}
.stream-chat-header, .chat-room__header, .chat-viewers__header {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(24,241,106,.22) !important;
  box-shadow: inset 0 -1px 0 rgba(24,241,106,.22) !important;
}
.chat-line__message, .vod-message, .seventv-chat-message {
  border-radius: 5px !important;
}
.chat-line__message:hover, .vod-message:hover, .seventv-chat-message:hover {
  background-color: rgba(12,91,39,.56) !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}
.chat-line__message--highlighted, .community-highlight-stack__card,
.chat-line__status, .chat-rules, .user-notice-line,
[data-a-target="chat-highlight"],
[data-test-selector="community-highlight-stack__card"] {
  background-color: rgba(4,54,27,.58) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
.chat-input {
  background-color: rgba(2,33,18,.42) !important;
  background-image: linear-gradient(125deg,
    rgba(21,100,54,.40) 0%, rgba(7,55,30,.28) 48%, rgba(1,20,13,.60) 100%) !important;
  box-shadow: inset 0 1px 0 rgba(85,255,143,.73), 0 0 27px rgba(0,255,105,.20) !important;
}
.chat-wysiwyg-input-box {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36) !important;
}
.chat-wysiwyg-input-box:focus-within {
  box-shadow: inset 0 0 0 1px #00ff66 !important;
}
[data-a-target="chat-input"], [data-a-target="chat-input"] [contenteditable="true"],
.chat-wysiwyg-input [contenteditable="true"], .chat-input textarea {
  color: #effff3 !important;
  caret-color: #38ff82 !important;
  border-color: rgba(28,240,102,.36) !important;
}
[data-a-target="chat-input"] [data-slate-placeholder],
.chat-wysiwyg-input [data-slate-placeholder] {
  color: #a6efbb !important;
  opacity: 1 !important;
}
.chat-input:focus-within {
  box-shadow: inset 0 1px 0 rgba(115,255,166,.95), 0 0 34px rgba(0,255,102,.27) !important;
}
.chat-input button[data-a-target="chat-send-button"] {
  background-color: #00e95d !important;
  color: #001609 !important;
  box-shadow: 0 0 12px rgba(0,255,102,.32) !important;
}
.chat-input button[data-a-target="chat-send-button"]:hover:not(:disabled) {
  background-color: #49ff90 !important;
}

/* 06. Menus, overlays, emote picker and dialogs. */
.tw-balloon, .tw-popover, .tw-tooltip, .tw-modal,
[role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"], [role="tooltip"],
[data-a-target="account-menu"], [data-a-target="search-tray"],
[data-a-target="chat-settings-balloon"], [data-a-target="emote-picker"],
[data-a-target="video-player-settings-menu"],
[data-a-target="player-settings-menu"], .chat-viewers__pane,
.viewer-card, .whispers__window, .emote-picker {
  background-color: rgba(1,23,10,.96) !important;
  color: #d9ffe5 !important;
  border-color: rgba(34,255,112,.41) !important;
  box-shadow: inset 0 0 0 1px rgba(34,255,112,.41),
    0 12px 35px rgba(0,0,0,.62), 0 0 18px rgba(0,180,67,.14) !important;
}
.tw-balloon [role="menu"], .tw-popover [role="menu"],
.tw-modal [role="dialog"], .tw-tooltip [role="tooltip"],
.tw-balloon [role="listbox"], .tw-popover [role="listbox"] {
  background-color: transparent !important;
  box-shadow: none !important;
}
[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"], [role="option"] {
  color: #cef9dc !important;
  border-radius: 7px !important;
}
[role="menuitem"]:hover, [role="menuitemradio"]:hover,
[role="menuitemcheckbox"]:hover, [role="option"]:hover,
[role="option"][aria-selected="true"], [role="menuitemradio"][aria-checked="true"] {
  background-color: rgba(12,103,43,.72) !important;
  color: #f0fff5 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}

/* 07. Forms, action buttons and player control accents. */
.tw-input, .tw-select, .tw-textarea,
input[type="text"], input[type="search"], input[type="email"],
input[type="password"], input[type="number"],
textarea, select {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #effff3 !important;
  caret-color: #38ff82 !important;
}
input::placeholder, textarea::placeholder {
  color: #a6efbb !important;
  opacity: 1 !important;
}
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: #00e85c !important;
}
.tw-button--primary {
  background-color: #00e85c !important;
  color: #001b09 !important;
}
.tw-button--primary:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: #38ff87 !important;
  color: #001b09 !important;
}
.tw-button--primary:active:not(:disabled):not([aria-disabled="true"]) {
  background-color: #00c84c !important;
}
.tw-button--secondary, .tw-button--outline {
  background-color: rgba(4,57,26,.88) !important;
  color: #d9ffe6 !important;
}
.tw-button--secondary:hover:not(:disabled):not([aria-disabled="true"]),
.tw-button--outline:hover:not(:disabled):not([aria-disabled="true"]),
.tw-button--text:hover:not(:disabled):not([aria-disabled="true"]),
.tw-icon-button:hover:not(:disabled):not([aria-disabled="true"]) {
  background-color: rgba(12,91,39,.56) !important;
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.50), 0 0 10px rgba(0,255,102,.09) !important;
}
button:focus-visible, a:focus-visible, input:focus-visible,
textarea:focus-visible, select:focus-visible, [role="button"]:focus-visible,
[role="tab"]:focus-visible, [contenteditable="true"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
/* Twitch paints the inner player black over the grid-bearing outer shell. */
.video-player .video-player__container,
.video-player [data-test-selector="video-player__video-container"],
.video-player .video-ref,
.video-player video {
  background-color: transparent !important;
}
.video-player .player-controls button:hover,
.video-player .player-controls [role="button"]:hover {
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.50) !important;
}
.video-player .seekbar-bar-fill, .video-player .seekbar-interaction-area__fill,
.video-player .seekbar-interaction-area__thumb,
.player-controls .seekbar-bar-fill {
  background-color: #00e85c !important;
}

/* 08. Scrollbar and scrollable chat chrome. */
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background-color: rgba(0,18,7,.18); }
*::-webkit-scrollbar-thumb { background-color: rgba(29,191,83,.53); border-radius: 8px; }
*::-webkit-scrollbar-thumb:hover { background-color: #70b68b; }
.simplebar-track, .scrollable-area .simplebar-track {
  background-color: rgba(0,18,7,.18) !important;
}
.simplebar-scrollbar::before {
  background-color: rgba(29,191,83,.53) !important;
}
.simplebar-scrollbar:hover::before { background-color: #70b68b !important; }
}
